  "export.note.generatedBy": "Generated by {{app}} — read-only export, no data was modified.",
  "export.note.unit":
    "Unit: the product schema has no unit field, so this column is intentionally blank.",
  "export.note.stockValue":
    "Stock value (cost) = current quantity × purchase price. Stock value (retail) = current quantity × sale price.",
  "export.note.returnedItems":
    "One row per returned line, so a multi-item return appears once per product. The refund actually paid out is on the Returns and Refunds sheets — a return's item values and its refund can differ when only part of it was refunded.",
  "export.note.totalsExcludeVoided":
    "Totals exclude voided invoices; voided rows are still listed and labelled.",
  "export.note.paymentSplit":
    "The Cash / Card / InstaPay columns split each invoice across its payments, so a split payment adds up to the invoice total.",
  "export.note.balance":
    "Balance = the unpaid portion of pending (unconfirmed) invoices. The app keeps no customer credit accounts.",
  "export.note.profit":
    "Cost of goods sold uses each product's current purchase price — sales do not snapshot cost, so profit is stated at today's costs.",
  "export.note.negativeIsOutflow":
    "Negative amounts are money out: cost of goods, expenses, returns and refunds.",
  "export.note.shiftRange": "A shift is included when it opened inside the selected date range.",
  "export.note.cashLedger":
    "Derived cash ledger: opening floats and cash sales in, cash refunds and cash expenses out. InstaPay and card never touch the drawer.",
  "export.note.suppliers":
    "This system keeps no supplier records. This sheet is derived from stock movements with a purchase or supplier-return reason, and from expenses — the only place a supplier name is ever typed.",
  "export.note.supplierGoodsValue":
    "Goods values are estimated at the product's current purchase price; a stock movement does not record the price it was bought at.",
  "export.note.netActivity":
    "Net activity = estimated goods received − estimated goods returned − expenses recorded. It is NOT an accounts-payable balance: the app never records supplier invoices.",
