  "dz.card.clear.title": "Clear Operational Data",
  "dz.card.clear.desc": "Wipe the day-to-day activity — sales, online orders, returns, shifts and their trees — by explicit groups you choose.",
  "dz.card.clear.keeps": "Keeps: products, variants, categories, branding, website, delivery/payment, staff.",
  "dz.card.clear.cta": "Clear operational data",
  "dz.card.demo.title": "Reset Demo / Test Data",
  "dz.card.demo.desc": "In demo mode every local record is a fixture; this restores the shipped sample shop to its freshly-seeded state.",
