  "dz.card.factory.title": "Factory Reset",
  "dz.card.factory.desc": "The catalogue, categories, website customization and every operational record — back to the shipped state. Staff accounts and the Super Admin always survive.",
  "dz.card.factory.keeps": "Always keeps: the Super Admin, staff accounts, schema, migrations.",
  "dz.card.factory.cta": "Factory reset",
  "dz.footer.serverSide": "Every destructive step runs as one server-side transaction with the manage_system_reset capability, a fresh password re-authentication, the exact confirmation phrase and a protected Super Admin verified before and after. The browser never deletes a row itself.",
  "dz.wizard.clear.title": "Clear operational data",
  "dz.wizard.factory.title": "Factory reset",
  "dz.step1.hint": "Choose exactly what this reset should delete. Everything you leave unticked is preserved.",
