  "dz.step1.cta": "Preview on the server",
  "dz.factory.always": "Factory reset always clears the operational floor first: sales, orders, returns, refunds, shifts, expenses, approvals and the stock ledger.",
  "dz.includedWithSales": "included with POS sales",
  "dz.error.nothing": "Choose at least one data group first.",
  "dz.error.password": "That password was not accepted.",
  "dz.step2.hint": "Counts below were calculated by the server just now — the preview changed nothing.",
  "dz.step2.cta": "I have reviewed the lists",
  "dz.willDelete": "Will be deleted",
  "dz.willKeep": "Will be preserved",
  "dz.resetToZero": "→ 0",
  "dz.preserve.admin": "Protected Super Admin",
  "dz.step4.hint": "Prove it is really you: enter the current password of the signed-in admin. It is verified by the sign-in service and never stored, logged or sent to the database.",
  "dz.step4.password": "Current password",
  "dz.step4.cta": "Verify password",
  "dz.step5.hint": "Type the exact phrase. This is the final gate before the server acts.",
  "dz.step5.phrase": "Confirmation phrase",
  "dz.step5.ack": "I understand this operation is atomic and cannot be undone from the app.",
  "dz.step5.serverSide": "The server re-checks your role, the fresh authentication, the phrase and the Super Admin before a single row moves.",
