  "holds.noQueueAccess": "You do not have access to the online orders queue.",
  "holds.explainer": "A pending website order holds its stock instead of deducting it, so the till and the website sell from the same number without overselling. Approving converts the hold into the sale's own deduction; cancelling releases it. Availability everywhere in the app is stock minus what is held here.",
  "holds.neverStock": "A repair settles the hold only — it never writes stock. The order's own transition already moved the shelf, so touching it again would be the double-count the reservation model exists to prevent. Every repair writes one audit row.",
