  // ── Phase 18 · Backup & recovery ────────────────────────────────────────
  // Five capabilities, one audit entity and seven verbs, and the panel that
  // holds them. The wording keeps two ideas apart on every screen: a snapshot
  // *exists* (metadata, `view_backups`) and a snapshot can be *held* (the file,
  // `export_backup`) — the difference between reassuring an owner and walking out
  // with the customer book.
