  // The health report's own words. One message saying what was found and one
  // recommendation saying what to do about it, keyed by the code the check
  // emits — so a code can be asserted in a test without pinning prose, and the
  // report reads in the operator's language rather than in a constant.
  // Mirrors the codes in src/modules/backup/services/health.ts, which the
  // selftest compares against these keys.
  "backup.health.negative_stock.message": "A product's stock level is below zero.",
  "backup.health.negative_stock.recommendation": "Recount it and write a stock adjustment: the adjustment adds the movement the ledger is missing.",
  "backup.health.movement_chain_gap.message": "A stock movement does not start where the one before it ended.",
  "backup.health.movement_chain_gap.recommendation": "Recount the product and write an adjustment. The gap stays in the ledger as the record of why.",
  "backup.health.stock_mismatch.message": "A product's level does not match the movements that produced it.",
  "backup.health.stock_mismatch.recommendation": "Recount and adjust. Until then, read the level on screen as an estimate rather than a count.",
  "backup.health.movement_orphan.message": "A stock movement points at a product that no longer exists.",
  "backup.health.movement_orphan.recommendation": "Leave it. Deleting a ledger row hides the loss it records; note the product it belonged to instead.",
  "backup.health.reservation_orphan.message": "A stock reservation points at a product or an order that no longer exists.",
  "backup.health.reservation_orphan.recommendation": "Release it from the online-orders screen: the stock it holds is protecting nothing.",
  "backup.health.reservation_stuck.message": "A reservation is still holding stock after it expired.",
  "backup.health.reservation_stuck.recommendation": "Release or convert it. Stock held for an order that is not coming is stock the till cannot sell.",
  "backup.health.reservation_invalid_quantity.message": "A reservation holds zero or a negative quantity.",
  "backup.health.reservation_invalid_quantity.recommendation": "Release it: it protects nothing, and it distorts what the storefront shows as available.",
  "backup.health.sale_without_items.message": "A sale has no lines on it.",
  "backup.health.sale_without_items.recommendation": "Void it if it was a mistake, or ring the goods up as a new sale. An empty invoice should not exist.",
  "backup.health.sale_item_orphan.message": "A sale line points at a sale that no longer exists.",
  "backup.health.sale_item_orphan.recommendation": "There is nothing to sell against. Leave the line and read totals from the sales, not from it.",
  "backup.health.sale_customer_orphan.message": "A sale names a customer who has been deleted.",
  "backup.health.sale_customer_orphan.recommendation": "The sale keeps the name and phone it was given, so its total is safe. Only the link is gone.",
  "backup.health.payment_orphan.message": "A payment points at a sale that no longer exists.",
  "backup.health.payment_orphan.recommendation": "Reconcile the day from the till report and record the difference as an adjustment.",
  "backup.health.payment_invalid_amount.message": "A payment is zero or negative.",
  "backup.health.payment_invalid_amount.recommendation": "Correct it against the sale it belongs to: a negative payment reads as a refund nobody approved.",
  "backup.health.overpaid_sale.message": "A sale's payments add up to more than its total.",
  "backup.health.overpaid_sale.recommendation": "Refund the difference or correct the payment; the drawer will not match until one of them happens.",
  "backup.health.return_orphan.message": "A return points at a sale that no longer exists.",
  "backup.health.return_orphan.recommendation": "The goods came back but the sale they came from did not. Note it against the day it happened.",
  "backup.health.return_item_orphan.message": "A returned line points at a return that no longer exists.",
  "backup.health.return_item_orphan.recommendation": "Leave it. The return's own totals are the record, and the line must not be restocked twice.",
  "backup.health.refund_orphan.message": "A refund points at a sale or a return that no longer exists.",
  "backup.health.refund_orphan.recommendation": "Settle or reject it explicitly, so the money ledger carries no open item that nobody owns.",
  "backup.health.online_order_item_orphan.message": "An online order line points at an order that no longer exists.",
  "backup.health.online_order_item_orphan.recommendation": "Release any hold it carries and leave the line: the order it belonged to is gone.",
  "backup.health.expense_orphan_shift.message": "An expense names a shift that no longer exists.",
  "backup.health.expense_orphan_shift.recommendation": "Move it to the shift it belongs to, or leave it and read that day's total without it.",
  "backup.health.expense_invalid_amount.message": "An expense is zero or negative.",
  "backup.health.expense_invalid_amount.recommendation": "Correct the amount: a negative expense inflates the profit of the day it was filed under.",
  "backup.health.user_invalid_role.message": "A staff account holds a role the system does not know.",
  "backup.health.user_invalid_role.recommendation": "Open the account in Users and assign a role. Until then it holds no capability at all.",
  "backup.health.user_orphan_custom_role.message": "A staff account points at a custom role that no longer exists.",
  "backup.health.user_orphan_custom_role.recommendation": "The account falls back to its base role. Reassign it if that is not what was intended.",
  "backup.health.role_unknown_capability.message": "A role lists a capability the system does not know.",
  "backup.health.role_unknown_capability.recommendation": "Edit the role and remove it: it enforces nothing, and it reads as a permission that exists.",
  "backup.health.user_unknown_exception.message": "A per-user exception names a capability the system does not know.",
  "backup.health.user_unknown_exception.recommendation": "Clear the exception on that account. It grants nothing and it hides a mistake.",
  "backup.health.user_contradictory_exception.message": "A user is both granted and denied the same capability.",
  "backup.health.user_contradictory_exception.recommendation": "The denial wins, so the account cannot do it. Clear one of the two if that was not intended.",
  "backup.health.no_active_admin.message": "No active staff account holds the admin role.",
  "backup.health.no_active_admin.recommendation": "Restore one immediately: without an admin nobody can change permissions, take a snapshot or restore one.",
